import React, { useState, useEffect } from "react";
import axios from "axios";

function App() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [message, setMessage] = useState("");
  const [googleUser, setGoogleUser] = useState(null);

  const register = async () => {
    try {
      const res = await axios.post("http://localhost:8000/register", {
        username,
        password,
      });
      setMessage(res.data.message);
    } catch (err) {
      setMessage(err.response?.data?.detail || "Error registering");
    }
  };

  const login = async () => {
    try {
      const res = await axios.post("http://localhost:8000/login", {
        username,
        password,
      });
      setMessage(res.data.message);
    } catch (err) {
      setMessage(err.response?.data?.detail || "Error logging in");
    }
  };

  // Handle Google Sign-In response
  const handleGoogleResponse = async (response) => {
    try {
      const credential = response.credential;
      const payload = JSON.parse(atob(credential.split('.')[1]));
      
      // Extract user info from the JWT payload
      const googleUserInfo = {
        email: payload.email,
        name: payload.name
      };
      
      setGoogleUser(googleUserInfo);
      
      // Send to backend
      const res = await axios.post("http://localhost:8000/google-login", googleUserInfo);
      setMessage(res.data.message);
    } catch (err) {
      setMessage(err.response?.data?.detail || "Error with Google Sign-In");
    }
  };

  // Initialize Google Sign-In
  useEffect(() => {
    // Initialize Google Sign-In when component mounts
    if (window.google) {
      window.google.accounts.id.initialize({
        client_id: "YOUR_GOOGLE_CLIENT_ID", // Replace with your actual Google Client ID
        callback: handleGoogleResponse,
      });

      window.google.accounts.id.renderButton(
        document.getElementById("google-signin"),
        { theme: "outline", size: "large", text: "signin_with", shape: "rectangular" }
      );
    }
  }, []);

  return (
    <div style={{ padding: "20px" }}>
      <h2>Login / Register</h2>
      <input
        placeholder="Username"
        value={username}
        onChange={(e) => setUsername(e.target.value)}
      />
      <br /><br />
      <input
        type="password"
        placeholder="Password"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
      />
      <br /><br />
      <button onClick={register}>Register</button>
      <button onClick={login} style={{ marginLeft: "10px" }}>Login</button>
      <br /><br />
      <div>
        <p>Or sign in with:</p>
        <div id="google-signin"></div>
      </div>
      <p>{message}</p>
      {googleUser && (
        <div>
          <p>Signed in as: {googleUser.name} ({googleUser.email})</p>
        </div>
      )}
    </div>
  );
}

export default App;
